function shelf(){renderers.forEach((r,i)=>{const offset=i-1,key=keys[(selected+offset+keys.length)%keys.length];r.angle=offset===0?-.18:offset*.4;r.set(key,designs[key]);r.canvas.parentElement.querySelector('span').textContent=names[key];r.canvas.parentElement.setAttribute('aria-label',offset===0?'Personalizar '+names[key]:'Selecionar '+names[key])});document.querySelectorAll('[data-product-color]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.productColor===designs[keys[selected]].color)))}
function move(delta){selected=(selected+delta+keys.length)%keys.length;shelf();const tiles=document.querySelectorAll('.product-tile');if(!matchMedia('(prefers-reduced-motion: reduce)').matches)tiles.forEach((tile,i)=>tile.animate([{opacity:.15,translate:(delta*15)+'px 0'},{opacity:i===1?1:.55,translate:'0 0'}],{duration:300,easing:'ease-out'}))}
function sync(){const key=keys[selected],s=designs[key];$('custom-product').value=key;$('custom-product-name').textContent=names[key];for(const [id,prop]of [['color','color'],['ink','ink'],['text','text'],['font','font'],['size','size'],['art-size','artSize'],['position','position'],['shape','shape']])$('custom-'+id).value=s[prop];$('custom-art').value='';$('custom-remove-art').hidden=!s.art;$('custom-shape').hidden=$('custom-shape-label').hidden=key!=='sticker';$('custom-feedback').textContent=s.artName?'Imagem: '+s.artName:'';editor.angle=0;editor.zoom=1;$('custom-orbit').value=0;$('custom-zoom').value=100;editor.set(key,s)}
