$('custom-product').addEventListener('change',()=>{uploadVersion++;selected=keys.indexOf($('custom-product').value);sync()});for(const [id,prop,numeric]of [['color','color'],['ink','ink'],['text','text'],['font','font'],['size','size',true],['art-size','artSize',true],['position','position',true],['shape','shape']])$('custom-'+id).addEventListener('input',()=>{designs[keys[selected]][prop]=numeric?Number($('custom-'+id).value):$('custom-'+id).value;editor.set(keys[selected],designs[keys[selected]])});
