$('custom-art').addEventListener('change',()=>{const file=$('custom-art').files[0],key=keys[selected],version=++uploadVersion;if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5*1024*1024){$('custom-feedback').textContent='Escolha uma imagem PNG, JPG ou WebP de até 5 MB.';return}const url=URL.createObjectURL(file),im=new Image();im.onload=()=>{URL.revokeObjectURL(url);if(version!==uploadVersion)return;if(im.width>12000||im.height>12000){$('custom-feedback').textContent='Use uma imagem com até 12.000 pixels por lado.';return}designs[key].art=im;designs[key].artName=file.name;sync()};im.onerror=()=>{URL.revokeObjectURL(url);$('custom-feedback').textContent='Não foi possível abrir esta imagem. Escolha outra.'};im.src=url});$('custom-remove-art').addEventListener('click',()=>{uploadVersion++;designs[keys[selected]].art=null;designs[keys[selected]].artName='';sync()});$('custom-reset').addEventListener('click',()=>{uploadVersion++;designs[keys[selected]]=defaults(keys[selected]);sync()});$('custom-surprise').addEventListener('click',()=>{const palettes=[['#00a9d9','#20211f'],['#ed008b','#ffffff'],['#f7f1e5','#a80064'],['#252a30','#ffdc16']];const pair=palettes[Math.floor(Math.random()*palettes.length)],s=designs[keys[selected]];s.color=pair[0];s.ink=pair[1];s.font=['sans','serif','mono'][Math.floor(Math.random()*3)];sync()});
